using NovaHarvest.Core.Crafting;
namespace NovaHarvest.Core.Systems; public sealed class CraftingSystem { readonly Inventory _inventory; readonly Dictionary<string, CraftingRecipe> _recipes = new(); public IReadOnlyCollection<CraftingRecipe> Recipes => _recipes.Values; public CraftingSystem(Inventory inventory) { _inventory = inventory; } public bool AddRecipe(CraftingRecipe r) { if (r is null || string.IsNullOrWhiteSpace(r.Id) || _recipes.ContainsKey(r.Id)) return false; _recipes.Add(r.Id, r); return true; } public CraftingRecipe? FindRecipe(string id) => _recipes.TryGetValue(id, out var r) ? r : null; public bool CanCraft(string id) { var r = FindRecipe(id); return r is not null && r.Materials.All(m => _inventory.Has(m.ItemId, m.Amount)); } public bool Craft(string id) { var r = FindRecipe(id); if (r is null || !CanCraft(id)) return false; foreach (var m in r.Materials) _inventory.Remove(m.ItemId, m.Amount); _inventory.Add(r.ResultItemId, r.ResultAmount); return true; } }
